import copy
import random
import unittest

from counting import BudgetExceeded, Counted, Ops, ShiftList, Tracked as T, CountingSeq as Seq, plain
from billing.engine import basket_total


def PRICE(key):
    s = str(key)
    return len(s) * 7 + ord(s[0]) % 13


def oracle(a, b):
    return sum(b(k) * q for k, q in a)


def wrap(a, b):
    return (a, Counted(b))

def small_args(rng):
    return ([(rng.randrange(0, 6), rng.randrange(1, 5)) for _ in range(rng.randrange(0, 15))], PRICE)


class CorrectnessTests(unittest.TestCase):
    def test_matches_the_reference_on_random_inputs(self):
        rng = random.Random(1000)
        for _ in range(120):
            args = small_args(rng)
            self.assertEqual(basket_total(*copy.deepcopy(args)), oracle(*copy.deepcopy(args)), args)

    def test_works_with_instrumented_values(self):
        rng = random.Random(1001)
        for _ in range(40):
            args = small_args(rng)
            self.assertEqual(plain(basket_total(*wrap(*copy.deepcopy(args)))), oracle(*copy.deepcopy(args)), args)

    def test_empty_inputs(self):
        empty = ([], PRICE)
        self.assertEqual(basket_total(*copy.deepcopy(empty)), oracle(*copy.deepcopy(empty)))

