import copy
import random
import unittest

from counting import BudgetExceeded, Counted, Ops, ShiftList, Tracked as T, CountingSeq as Seq, plain
from billing.engine import basket_total


def PRICE(key):
    s = str(key)
    return len(s) * 7 + ord(s[0]) % 13


def oracle(a, b):
    return sum(b(k) * q for k, q in a)


def wrap(a, b):
    return (a, Counted(b))

def big_args(rng, n):
    return ([(rng.randrange(0, 40), rng.randrange(1, 9)) for _ in range(n)], PRICE)


class PerformanceTests(unittest.TestCase):
    def test_cost_grows_with_the_input(self):
        rng = random.Random(1000)
        n = 1500
        args = big_args(rng, n)
        wrapped = wrap(*copy.deepcopy(args))
        limit = 0.25 * n
        Ops.reset()
        Ops.budget = limit * 20
        try:
            got = basket_total(*wrapped)
        except BudgetExceeded:
            self.fail("PERF: gave up after %d calls to the collaborator for %d items (limit %d): the collaborator is called repeatedly for the same arguments" % (Ops.budget, n, limit))
        finally:
            Ops.budget = None
        ops = Ops.reads
        self.assertEqual(plain(got), oracle(*copy.deepcopy(args)))
        self.assertLessEqual(ops, limit, "PERF: %d calls to the collaborator for %d items (limit %d): the collaborator is called repeatedly for the same arguments" % (ops, n, limit))

solution.billing/engine.py:
"""billing: small helpers used by the batch jobs."""


def basket_total(lines, price_of):
    """Total of a basket, pricing each line through the catalogue service."""
    cache = {}
    total = 0
    for key, qty in lines:
        if key not in cache:
            cache[key] = price_of(key)
        total += cache[key] * qty
    return total


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

