import random
import unittest

from counting import BudgetExceeded, Counted, Ops, ShiftList, Tracked as T, CountingSeq as Seq, plain
from routing.report import live_prices


def FETCH(key):
    if key % 5 == 0:
        return None
    return {"ok": key % 3 != 0, "v": key * 2 + 1}


def oracle(a, b):
