            args = small_args(rng)
            self.assertEqual(live_prices(*copy.deepcopy(args)), oracle(*copy.deepcopy(args)), args)

    def test_works_with_instrumented_values(self):
        rng = random.Random(1002)
        for _ in range(40):
            args = small_args(rng)
            self.assertEqual(plain(live_prices(*wrap(*copy.deepcopy(args)))), oracle(*copy.deepcopy(args)), args)

    def test_empty_inputs(self):
        empty = ([], FETCH)
        self.assertEqual(live_prices(*copy.deepcopy(empty)), oracle(*copy.deepcopy(empty)))

