    def __lt__(self, other):
        Ops.lt += 1
        Ops.tick()
        return self.v < other.v

    def __le__(self, other):
        Ops.lt += 1
        Ops.tick()
        return self.v <= other.v

    def __gt__(self, other):
        Ops.lt += 1
        Ops.tick()
        return self.v > other.v

    def __ge__(self, other):
        Ops.lt += 1
        Ops.tick()
        return self.v >= other.v

    def __hash__(self):
        Ops.hash += 1
        Ops.tick()
        return hash(self.v)

