"""orgchart: small helpers used by the batch jobs."""


def approved_totals(order_ids, load):
    """Totals of orders that exist and are approved."""
    out = []
    for key in order_ids:
        record = load(key)
        if record is not None and record["ok"]:
            out.append(record["v"])
    return out


def describe(count, noun):
    """Pluralised count for log lines."""
    return "%d %s%s" % (count, noun, "" if count == 1 else "s")

